from typing import Union

from .exceptions import UnsupportedParametersError


class ParametersValidator:

    @staticmethod
    def validate_parameters(available_parameters: Union[set, list, dict],
                            selected_parameters: Union[set, list, dict]
                            ) -> None:
        """
        Method compares inserted and available params.

        :param (set|list|dict) available_parameters:
        :param (set|list|dict) selected_parameters:
        """
        if not (set(selected_parameters).issubset(set(available_parameters))):
            raise UnsupportedParametersError
